module Auditable
  def self.included(base)
    base.extend(ClassMethods)
  end
  module ClassMethods
    def track_changes(*attributes)
      @tracked_attributes = attributes
    end
    def tracked_attributes
      @tracked_attributes || []
    end
  end
end

queue = Thread::Queue.new
producer = Thread.new { 10.times { |i| queue << i } }
consumer = Thread.new { 10.times { puts "Consumed: #{queue.pop}" } }
[producer, consumer].each(&:join)
